    40.4093, 49.8671, 2303100,
    'Baku is the capital and largest city of Azerbaijan, as well as the largest city on the Caspian Sea and in the Caucasus region. Baku is 28 metres (92 ft) below sea level, which makes it the lowest lying national capital in the world and the largest city in the world below sea level. Baku lies on the southern shore of the Absheron Peninsula, along the Bay of Baku. Baku''s urban population was estimated at two million people as of 2009. Baku is the primate city of Azerbaijan. It is the sole metropolis in the country, and about 25% of all inhabitants of the country live in Baku''s metropolitan area.', 'Baku is the capital and largest city of Azerbaijan, as well as the largest city on the Caspian Sea and in the Caucasus region. Baku is 28 metres (92 ft) below sea level, which makes it the lowest lying national capital in the world and the largest city in the world below sea level. Baku lies on the southern shore of the Absheron Peninsula, along the Bay of Baku. Baku''s urban population was estimated at two million people as of 2009. Baku is the primate city of Azerbaijan. It is the sole metropolis in the country, and about 25% of all inhabitants of the country live in Baku''s metropolitan area.',
    'wikipedia', 'https://en.wikipedia.org/wiki/Baku', 'CC BY-SA', 'Wikipedia contributors, Baku', now()
  from country_ref
  on conflict (country_id, slug) do update set
    name_az = excluded.name_az,
    name_en = excluded.name_en,
    name_ru = excluded.name_ru,
    lat = excluded.lat,
    lng = excluded.lng,
    population = excluded.population,
    short_desc_en = excluded.short_desc_en,
    description_en = excluded.description_en,
    source = excluded.source,
    source_url = excluded.source_url,
    license = excluded.license,
    attribution_text = excluded.attribution_text,
    last_synced_at = now()
  returning id, country_id
